IF DB_ID(N'ClinicDB') IS NULL CREATE DATABASE ClinicDB;
GO
USE ClinicDB;
GO
IF OBJECT_ID(N'dbo.BenhNhan',N'U') IS NULL CREATE TABLE dbo.BenhNhan(MaBN INT IDENTITY PRIMARY KEY,HoTen NVARCHAR(100) NOT NULL,SoDienThoai VARCHAR(15) NOT NULL UNIQUE,NamSinh INT NULL);
IF OBJECT_ID(N'dbo.HoSoKham',N'U') IS NULL CREATE TABLE dbo.HoSoKham(MaHoSo INT IDENTITY PRIMARY KEY,MaBN INT NOT NULL REFERENCES dbo.BenhNhan(MaBN),NgayKham DATETIME NOT NULL DEFAULT GETDATE(),TrieuChung NVARCHAR(MAX) NULL,ChanDoan NVARCHAR(250) NULL);
IF OBJECT_ID(N'dbo.Thuoc',N'U') IS NULL CREATE TABLE dbo.Thuoc(MaThuoc INT IDENTITY PRIMARY KEY,TenThuoc NVARCHAR(150) NOT NULL,DonViTinh NVARCHAR(20) NOT NULL,DonGia DECIMAL(18,2) NOT NULL CHECK(DonGia>=0),SoLuongTon INT NOT NULL CHECK(SoLuongTon>=0));
IF OBJECT_ID(N'dbo.DonThuoc',N'U') IS NULL CREATE TABLE dbo.DonThuoc(MaDon INT IDENTITY PRIMARY KEY,MaHoSo INT NOT NULL REFERENCES dbo.HoSoKham(MaHoSo),TienKham DECIMAL(18,2) NOT NULL,TongTien DECIMAL(18,2) NOT NULL,TrangThai NVARCHAR(30) NOT NULL DEFAULT N'Chờ thanh toán');
IF OBJECT_ID(N'dbo.ChiTietDonThuoc',N'U') IS NULL CREATE TABLE dbo.ChiTietDonThuoc(MaDon INT NOT NULL REFERENCES dbo.DonThuoc(MaDon),MaThuoc INT NOT NULL REFERENCES dbo.Thuoc(MaThuoc),SoLuong INT NOT NULL CHECK(SoLuong>0),LieuDung NVARCHAR(100) NOT NULL,CONSTRAINT PK_ChiTietDonThuoc PRIMARY KEY(MaDon,MaThuoc));
IF NOT EXISTS(SELECT 1 FROM dbo.BenhNhan) INSERT dbo.BenhNhan(HoTen,SoDienThoai,NamSinh) VALUES(N'Phạm Thị Mai','0901234567',1987),(N'Nguyễn Văn Long','0912345678',1975),(N'Lê Minh Châu','0987654321',2001);
IF NOT EXISTS(SELECT 1 FROM dbo.Thuoc) INSERT dbo.Thuoc(TenThuoc,DonViTinh,DonGia,SoLuongTon) VALUES(N'Paracetamol 500mg',N'Viên',1200,250),(N'Amoxicillin 500mg',N'Viên',2500,140),(N'Vitamin C',N'Viên',900,180),(N'Siro ho thảo dược',N'Chai',42000,35);
IF NOT EXISTS(SELECT 1 FROM dbo.HoSoKham) INSERT dbo.HoSoKham(MaBN,NgayKham,TrieuChung,ChanDoan) SELECT MIN(MaBN),DATEADD(day,-1,GETDATE()),N'Đau đầu, sốt nhẹ',N'Cảm cúm thông thường' FROM dbo.BenhNhan;
GO
